INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2360, 2451, NULL, (N'SP-NAM-JEAN-02'), (N'Quần Jean Nam Slimfit Denim 12.5oz Co Giãn Cao Cấp'), (N'quan-jean-nam-slimfit-denim-12oz'), (N'Denim co giãn Spandex'), (N'Slim Fit'), (N'Quần jean nam thiết kế ống côn ôm nhẹ tôn dáng, sợi Spandex co giãn 4 chiều cho cảm giác vận động thoải mái tối đa. Khóa kéo kim loại YKK bền bỉ và wash màu phong trần hiện đại.'), (N'Size 29: Vòng bụng 75-77cm | Size 30: Vòng bụng 78-80cm | Size 31: Vòng bụng 81-83cm | Size 32: Vòng bụng 84-86cm'), 420000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T15:49:55.3733333',126), NULL, NULL, NULL);
