INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2365, 2454, NULL, (N'SP-NU-QUANTAY-07'), (N'Quần Tây Nữ Ống Suông Cạp Cao Hack Dáng Simplain'), (N'quan-tay-nu-ong-suong-cap-cao'), (N'Tuyết mưa cao cấp'), (N'Ống rộng (Wide Leg)'), (N'Quần tây nữ cạp cao phối khóa ẩn thanh lịch, ống suông dài chuẩn tỷ lệ hack chân dài miên man. Vải tuyết mưa dệt đanh sợi, chống nhăn và chống bám bụi hiệu quả.'), (N'Size S: Vòng eo 63-66cm (43-48kg) | Size M: Vòng eo 67-70cm (49-54kg) | Size L: Vòng eo 71-75cm (55-60kg)'), 350000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T15:49:55.4366667',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2366, 2445, NULL, (N'SP-GIAY-SNEAKER-08'), (N'Giày Sneaker Thể Thao Đệm Khí Êm Chân Simplain Runner'), (N'giay-sneaker-the-thao-dem-khi-simplain'), (N'Vải Flyknit thoáng khí'), (N'Low-Top cổ thấp'), (N'Giày sneaker thể thao với thân dệt Flyknit nguyên khối co giãn ôm sát mu bàn chân, đế đệm trợ lực êm ái bảo vệ khớp xương khi đi bộ hay chạy nhảy. Đế ngoài phủ cao su chống mài mòn và bám đường tối ưu.'), (N'Size 39: Chân 24.1 - 24.5cm | Size 40: 24.6 - 25.0cm | Size 41: 25.1 - 25.5cm | Size 42: 25.6 - 26.0cm'), 590000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T15:49:55.4466667',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2367, 2446, NULL, (N'SP-GIAY-SANDAL-09'), (N'Giày Sandal Nam Nữ Quai Dù Đế Bánh Mì Siêu Êm'), (N'giay-sandal-nam-nu-quai-du-de-banh-mi'), (N'Cao su lưu hóa chống trơn'), (N'Low-Top cổ thấp'), (N'Sandal quai hậu bản dù jacquard chịu lực cao, khóa dán thông minh điều chỉnh độ ôm chân linh hoạt. Đế bánh mì đúc cao su non siêu nhẹ, êm ái chống trơn trượt hoàn hảo khi đi mưa.'), (N'Size 38: Chân dài 23.5 - 24.0cm | Size 39: 24.1 - 24.5cm | Size 40: 24.6 - 25.0cm | Size 41: 25.1 - 25.5cm'), 320000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T15:49:55.4600000',126), NULL, NULL, NULL);
