INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2373, 2458, NULL, (N'SP-PK-KINHMAT-15'), (N'Kính Mát Unisex Gọng Titanium Phân Cực Polarized Chống UV400'), (N'kinh-mat-unisex-gong-titanium-polarized'), (N'Titanium mạ PVD siêu bền'), (N'Mặt tròn cổ điển'), (N'Kính mát phân cực cao cấp gọng hợp kim Titanium siêu nhẹ, chịu lực uốn cong linh hoạt không biến dạng. Tròng kính tráng gương 9 lớp bảo vệ mắt tối đa khỏi 100% tia tử ngoại UV400 và chống lóa đèn xe ban đêm.'), (N'Chiều ngang tròng: 54mm | Cầu kính: 18mm | Chiều dài càng kính: 142mm (Khối lượng siêu nhẹ chỉ 18g)'), 350000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T15:49:55.5200000',126), NULL, NULL, NULL);
