INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2383, 2462, NULL, (N'SP-TUI-XACH-11'), (N'Túi Xách Da Bò Epsom Nữ Khóa Gập Thanh Lịch Simplain'), (N'tui-xach-da-bo-epsom-nu-thanh-lich'), (N'Da bò hạt Epsom'), (N'Túi bao tử (Chest Bag)'), (N'Túi xách nữ chất liệu da bò Epsom dập vân tinh tế chống trầy xước và kháng nước, phụ kiện khóa xoay mạ vàng sáng bóng sang trọng. Dây đeo da phối xích có thể điều chỉnh đeo chéo hoặc xách tay linh hoạt.'), (N'Kích thước tiêu chuẩn: Chiều dài 24cm x Rộng 8cm x Cao 16cm (Chứa vừa iPad Mini, điện thoại, ví dài)'), 520000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T21:20:27.9600000',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2384, 2463, NULL, (N'SP-BALO-LAPTOP-12'), (N'Balo Laptop Công Sở Kháng Nước Đa Năng Simplain 20L'), (N'balo-laptop-cong-so-khang-nuoc-simplain'), (N'Vải Canvas chống nước'), (N'Balo nắp cuộn (Roll-top)'), (N'Balo công sở thiết kế tối giản thông minh, chất vải Canvas 900D phủ tráng PU chống thấm nước khi đi mưa. Đệm lưng tổ ong thoáng khí thoát nhiệt, quai đeo trợ lực chống gù lưng hiệu quả.'), (N'Form chuẩn 20L: 43cm x 30cm x 14cm (Có ngăn chống sốc chuyên dụng đựng laptop 15.6 inch)'), 420000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T21:20:27.9666667',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2385, 2464, NULL, (N'SP-PK-DONGHO-14'), (N'Đồng Hồ Nam Dây Thép Không Gỉ Mặt Kính Sapphire Simplain Classic'), (N'dong-ho-nam-thep-khong-gi-mat-sapphire'), (N'Thép không gỉ 316L'), (N'Mặt tròn cổ điển'), (N'Đồng hồ nam phong cách doanh nhân lịch lãm, bộ máy Quartz chuẩn xác từ Nhật Bản. Toàn bộ vỏ và dây đeo chế tác từ thép không gỉ 316L chống ăn mòn tuyệt đối, mặt kính tinh thể Sapphire chống va đập trầy xước.'), (N'Đường kính mặt 40mm | Độ dày vỏ 8.5mm | Chiều dài dây 220mm (Kính Sapphire chống xước, chống nước 5ATM)'), 890000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T21:20:27.9800000',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2386, 2465, NULL, (N'SP-PK-THAT-LUNG-17'), (N'Thắt Lưng Nam Da Bò Sáp Khóa Kim Loại Tự Động Cao Cấp'), (N'that-lung-nam-da-bo-khoa-tu-dong-cao-cap'), (N'Da bò sáp nguyên tấm'), (N'Regular Fit'), (N'Dây nịt nam da bò thuộc 2 lớp dẻo dai nguyên tấm, không bong tróc hay rạn nứt bề mặt. Khóa ray trượt tự động hợp kim mạ crom sáng bóng, thao tác cài mở êm mượt và sang trọng.'), (N'Bản rộng 3.5cm x Chiều dài 120cm (Phù hợp vòng bụng từ 75cm đến 105cm, dễ cắt bớt dây)'), 290000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T21:20:28.0000000',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2387, 2466, NULL, (N'SP-PK-TRANGSUC-18'), (N'Vòng Tay Bạc Ý 925 Xi Bạch Kim Mắt Xích Cuban Nam Nữ'), (N'vong-tay-bac-y-925-cuban-chain'), (N'Bạc Ý 925 xi bạch kim'), (N'Dây xích Cuban cá tính'), (N'Lắc tay bạc chuẩn 92.5% phủ lớp mạ Rhodium bạch kim bóng bẩy, chống ố xỉn và không gây kích ứng da. Thiết kế mắt xích Cuban đan cài mạnh mẽ, phong cách streetwear thời thượng nâng tầm cổ tay.'), (N'Chiều dài lắc 18cm + 3cm mắt xích mở rộng (Bản xích dày 5mm, khối lượng 14.2 gram)'), 390000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T21:20:28.0033333',126), NULL, NULL, NULL);
INSERT INTO [dbo].[san_pham] ([id], [ma_danh_muc_id], [ma_bo_suu_tap_id], [ma_san_pham], [ten_san_pham], [duong_dan_slug], [chat_lieu], [form_dang], [mo_ta_chi_tiet], [huong_dan_chon_size], [gia_co_ban], [noi_bat], [kich_hoat], [ngay_tao], [ma_chat_lieu_id], [ma_form_dang_id], [video_url]) VALUES (2388, 2467, NULL, (N'SP-PK-KHANCHOANG-19'), (N'Khăn Choàng Cổ Len Cashmere Giữ Ấm Mùa Đông Cao Cấp'), (N'khan-choang-co-len-cashmere-cao-cap'), (N'Len Cashmere cao cấp'), (N'Regular Fit'), (N'Khăn choàng cổ dệt từ sợi len Cashmere cao cấp kết hợp lông cừu tự nhiên, mang lại cảm giác mềm mại như nhung, không gây dặm ngứa da cổ. Hai đầu khăn đan tua rua cổ điển thanh lịch, giữ ấm cơ thể hoàn hảo trong ngày đông giá rét.'), (N'Kích thước tiêu chuẩn: Chiều dài 200cm x Rộng 70cm (Khối lượng 260g siêu nhẹ giữ nhiệt tối ưu)'), 310000, 1, 1, CONVERT(datetime2(7),N'2026-11-05T21:20:28.0100000',126), NULL, NULL, NULL);
